// Si llegamos aqui, la cabecera X-Telegram-Bot-Api-Secret-Token ya era
// valida: la comprobo n8n en el nodo Webhook (§4.2).
const e = $input.first().json;
const b = e.body || {};
const cb = b.callback_query;
const msg = b.message || b.edited_message;

let chat_id = null, tipo = 'otro', texto = null, dato = null;

if (cb) {
  chat_id = (cb.message && cb.message.chat && cb.message.chat.id) ||
            (cb.from && cb.from.id) || null;
  tipo = 'boton';
  dato = typeof cb.data === 'string' ? cb.data : '';
} else if (msg) {
  chat_id = (msg.chat && msg.chat.id) || null;
  if (typeof msg.text === 'string' && msg.text.length > 0) {
    tipo = 'texto';
    texto = msg.text;
  }
  // Sin texto (foto, sticker, audio) se queda en tipo 'otro': se repetira la
  // pregunta actual, no se interpretara como respuesta.
}

// Un update sin chat no nos toca. Devolver [] termina la rama sin hacer nada.
if (chat_id === null || chat_id === undefined) { return []; }

return [{ json: { chat_id, tipo, texto, dato } }];

// LA TABLA DE LAS 7 PREGUNTAS DEL §4.4 DEL SPEC.
//
// Es la UNICA fuente de la que sale (a) la clave con la que se guarda cada
// respuesta y (b) los valores que se aceptan. Los teclados de los nodos
// `Pregunta 1..7` repiten los mismos callback_data, y
// tests/test_flujo_paciente.py compara AMBAS cosas contra el §4.4 leyendo el
// JSON exportado: si divergieran, la suite se pone roja sin necesidad de
// tunel, base de datos ni secretos.
//
// Por que tanto cuidado: una respuesta guardada en la clave de OTRA pregunta
// no da error. Entra en el jsonb, viaja al profesional, y sale como una
// probabilidad previa equivocada en H6 que nadie ve.
const PREGUNTAS = [
  {n: 1, clave: 'fiebre',         valores: ['si', 'no', 'no_se']},
  {n: 2, clave: 'tos',            valores: ['con_flema', 'seca', 'no']},
  {n: 3, clave: 'dias_evolucion', valores: ['menos_3', '3_a_7', 'mas_7']},
  {n: 4, clave: 'disnea',         valores: ['si', 'no']},
  {n: 5, clave: 'dolor_toracico', valores: ['si', 'no']},
  {n: 6, clave: 'asma',           valores: ['si', 'no', 'no_se']},
  {n: 7, clave: 'texto_libre',    valores: ['omitir']},
];
const ULTIMA = 7;

const u = $('Normalizar update').first().json;
const s = $input.first().json;

const texto = (u.texto || '').trim();
const bajo = texto.toLowerCase();
const esComando = (c) =>
  bajo === c || bajo.startsWith(c + ' ') || bajo.startsWith(c + '@');

// El valor viaja a SQL en base64. El nodo Postgres pasa sus parametros en una
// lista SEPARADA POR COMAS, asi que un texto libre con una coma se partiria en
// dos parametros y la consulta fallaria o, peor, guardaria otra cosa. El
// alfabeto de base64 no tiene comas. Se decodifica dentro de la consulta, que
// sigue siendo parametrizada: desde Telegram no se puede inyectar SQL.
const b64 = (v) => Buffer.from(v, 'utf8').toString('base64');

const salida = {
  chat_id: u.chat_id,
  accion: 'nada',
  clave: '',
  valor_b64: '',
  paso: 0,             // el paso que se va a preguntar o a repetir
  paso_actual: s.paso, // el que la sesion tiene AHORA, para el UPDATE
};

const actual = PREGUNTAS.find((p) => p.n === s.paso);

if (u.tipo === 'texto' && esComando('/reiniciar')) {
  // Destructivo, y pedido a proposito: borra la sesion y vuelve al consentimiento (§6).
  salida.accion = 'consentimiento';
} else if (u.tipo === 'texto' && esComando('/start')) {
  // /start con un cuestionario A MEDIAS no lo borra: repite la pregunta en la
  // que estaba. Borrarlo aqui perderia en silencio las respuestas ya dadas, y
  // el spec no pide que /start sea destructivo: el que lo es es /reiniciar.
  // Si no hay nada que contestar -sin sesion, o parada en el paso 8 porque
  // fallo la generacion del codigo- entonces si vuelve al consentimiento, que
  // es como se sale de ahi.
  if (actual && s.consentido) {
    salida.accion = 'repetir';
    salida.paso = actual.n;
  } else {
    salida.accion = 'consentimiento';
  }
} else if (u.tipo === 'boton' && u.dato === 'consent:no') {
  salida.accion = 'despedida';
} else if (u.tipo === 'boton' && u.dato === 'consent:si') {
  // Si YA hay sesion, este boton es viejo o es un doble toque. Aceptarlo
  // reiniciaria el cuestionario y borraria las respuestas ya dadas.
  salida.accion = s.existe ? (actual ? 'repetir' : 'nada') : 'aceptar';
  salida.paso = actual ? actual.n : 0;
} else if (!s.existe || !s.consentido || !actual) {
  // Sin consentimiento no se guarda NADA (D11), y sin sesion no hay pregunta
  // que repetir: contestar aqui seria hablarle a quien no ha dicho /start.
  salida.accion = 'nada';
} else if (u.tipo === 'boton') {
  const m = /^p([1-7]):(.+)$/.exec(u.dato || '');
  if (!m) {
    salida.accion = 'nada';            // callback ajeno o forjado
  } else if (Number(m[1]) !== actual.n || actual.valores.indexOf(m[2]) < 0) {
    salida.accion = 'repetir';         // boton de otra pregunta o valor que
    salida.paso = actual.n;            // el §4.4 no permite
  } else {
    salida.accion = 'guardar';
    salida.clave = actual.clave;
    // 'omitir' en la 7 significa texto_libre = null, no la cadena 'omitir'.
    salida.valor_b64 =
      (actual.n === ULTIMA && m[2] === 'omitir') ? '' : b64(m[2]);
    salida.paso = actual.n + 1;
  }
} else if (u.tipo === 'texto' && actual.n === ULTIMA) {
  // La 7 es la unica que admite texto libre. Se recorta a 500 caracteres
  // (§4.4) y no alimenta ningun calculo (D4).
  salida.accion = 'guardar';
  salida.clave = actual.clave;
  salida.valor_b64 = b64(texto.slice(0, 500));
  salida.paso = ULTIMA + 1;
} else {
  // Texto donde se esperaba un boton, una foto, un sticker: se repite la
  // pregunta actual (§6).
  salida.accion = 'repetir';
  salida.paso = actual.n;
}

return [{ json: salida }];
